INSERT INTO users(organization_id,first_name,last_name,email,phone,password_hash,status,must_change_password)
INSERT INTO user_roles(user_id,role_id,project_id,state_id) SELECT u.id,r.id,p.id,s.id FROM users u JOIN organizations o ON o.id=u.organization_id JOIN roles r ON r.code='FACILITATOR' JOIN projects p ON p.organization_id=o.id AND p.code='VSLA-PILOT' JOIN states s ON s.name='Niger' AND s.country_code='NG' WHERE u.email IN ('amina.facilitator@example.org','james.facilitator@example.org') ON CONFLICT DO NOTHING;
INSERT INTO facilitator_profiles(user_id,staff_code,state_id,lga_id,status) SELECT u.id,CASE WHEN u.email LIKE 'amina%' THEN 'FAC-001' ELSE 'FAC-002' END,s.id,l.id,'ACTIVE' FROM users u JOIN states s ON s.name='Niger' AND s.country_code='NG' JOIN lgas l ON l.state_id=s.id AND l.name=CASE WHEN u.email LIKE 'amina%' THEN 'Chanchaga' ELSE 'Suleja' END WHERE u.email IN ('amina.facilitator@example.org','james.facilitator@example.org') ON CONFLICT(user_id) DO NOTHING;
INSERT INTO vsla_groups(organization_id,project_id,group_code,name,state_id,lga_id,community_id,facilitator_user_id,date_formed,meeting_location,group_type,status)
