-- Facilitator accounts are created with unusable random hashes and must be assigned passwords by an administrator.
SELECT o.id,v.first_name,v.last_name,v.email,v.phone,crypt(gen_random_uuid()::text,gen_salt('bf')),'ACTIVE',true FROM organizations o CROSS JOIN (VALUES('Amina','Bello','amina.facilitator@example.org','08000000001'),('James','Musa','james.facilitator@example.org','08000000002')) v(first_name,last_name,email,phone) WHERE o.code='CCCRN' ON CONFLICT DO NOTHING;
SELECT o.id,p.id,v.code,v.name,s.id,l.id,c.id,u.id,CURRENT_DATE-30,v.location,'SUPERVISED',v.status FROM organizations o JOIN projects p ON p.organization_id=o.id AND p.code='VSLA-PILOT' JOIN states s ON s.name='Niger' AND s.country_code='NG' CROSS JOIN (VALUES('CCCRN-NIG-MNA-0001','Unity Women VSLA','Chanchaga','amina.facilitator@example.org','Community Hall','ONBOARDING'),('CCCRN-NIG-MNA-0002','Progress VSLA','Chanchaga','amina.facilitator@example.org','Primary School','ONBOARDING'),('CCCRN-NIG-SUL-0001','Hope Savers','Suleja','james.facilitator@example.org','Ward Centre','ACTIVE'),('CCCRN-NIG-SUL-0002','Future Builders','Suleja','james.facilitator@example.org','Town Hall','ACTIVE')) v(code,name,lga,email,location,status) JOIN lgas l ON l.state_id=s.id AND l.name=v.lga JOIN communities c ON c.lga_id=l.id JOIN users u ON u.organization_id=o.id AND u.email=v.email WHERE o.code='CCCRN' ON CONFLICT(organization_id,group_code) DO NOTHING;
